#pragma GCC optimize("O3,unroll-loops,omit-frame-pointer,inline-functions")
#pragma GCC target("avx2,bmi,bmi2,lzcnt,popcnt")

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

#define MAX_N 26

static int n;
static int region[MAX_N][MAX_N];

/* Column containing the cat in each row. */
static int positions[MAX_N];

/* First solution found by the solver. */
static int solution[MAX_N];

/* Number of solutions found, capped at 2. */
static int solution_count = 0;

/*
 * Backtracking solver.
 *
 * row:             Current row to process.
 * used_columns:    Bitmask of occupied columns.
 * used_regions:    Bitmask of occupied regions.
 * previous_column: Column of the cat in the previous row.
 *
 * Since every row contains exactly one cat,
 * only cats in consecutive rows can touch diagonally.
 */
static void solve(int row,
                  uint32_t used_columns,
                  uint32_t used_regions,
                  int previous_column)
{
    /* Stop once multiple solutions have been found. */
    if (solution_count >= 2)
        return;

    /* All rows have been assigned. */
    if (row == n) {
        ++solution_count;

        /* Save the first solution. */
        if (solution_count == 1) {
            for (int r = 0; r < n; ++r)
                solution[r] = positions[r];
        }

        return;
    }

    /* Try placing the cat in each column. */
    for (int c = 0; c < n; ++c) {
        int id = region[row][c];

        uint32_t col_bit = UINT32_C(1) << c;
        uint32_t reg_bit = UINT32_C(1) << id;

        /* Exactly one cat per column. */
        if (used_columns & col_bit)
            continue;

        /* Exactly one cat per region. */
        if (used_regions & reg_bit)
            continue;

        /*
         * Cats in consecutive rows must have
         * a column distance of at least 2.
         *
         * Same-column placement is already excluded
         * by used_columns.
         */
        if (row > 0 &&
            abs(c - previous_column) <= 1)
            continue;

        /* Place the cat. */
        positions[row] = c;

        /* Recursively solve the next row. */
        solve(row + 1,
              used_columns | col_bit,
              used_regions | reg_bit,
              c);

        if (solution_count >= 2)
            return;
    }
}

/*
 * Read the grid size and region layout from stdin.
 *
 * Expected format:
 *
 * 4
 * A A B B
 * A C B B
 * A C C D
 * C C D D
 *
 * Exactly n different region letters must occur.
 */
static int read_puzzle(void)
{
    if (scanf("%d", &n) != 1) {
        fprintf(stderr, "Error: Cannot read grid size.\n");
        return 0;
    }

    if (n < 4 || n > MAX_N) {
        fprintf(stderr,
                "Error: Grid size must be between 4 and %d.\n",
                MAX_N);
        return 0;
    }

    uint32_t seen_regions = 0;

    for (int r = 0; r < n; ++r) {
        for (int c = 0; c < n; ++c) {
            char ch;

            if (scanf(" %c", &ch) != 1) {
                fprintf(stderr,
                        "Error: Cannot read cell (%d, %d).\n",
                        r, c);
                return 0;
            }

            /* Valid region labels are A through A+n-1. */
            if (ch < 'A' || ch >= 'A' + n) {
                fprintf(stderr,
                        "Error: Invalid region '%c' "
                        "at (%d, %d).\n",
                        ch, r, c);
                return 0;
            }

            int id = ch - 'A';

            region[r][c] = id;
            seen_regions |= UINT32_C(1) << id;
        }
    }

    /* Verify that all n regions are present. */
    uint32_t expected = (UINT32_C(1) << n) - 1;

    if (seen_regions != expected) {
        fprintf(stderr,
                "Error: Puzzle must contain "
                "exactly %d regions (A through %c).\n",
                n, 'A' + n - 1);
        return 0;
    }

    return 1;
}

/*
 * Print the solved puzzle.
 *
 * Cat positions use lowercase region letters.
 * All other cells retain their uppercase letters.
 */
static void print_solution(void)
{
    for (int r = 0; r < n; ++r) {
        for (int c = 0; c < n; ++c) {
            char ch = (char)('A' + region[r][c]);

            if (solution[r] == c)
                ch = (char)('a' + region[r][c]);

            putchar(ch);

            if (c + 1 < n)
                putchar(' ');
        }

        putchar('\n');
    }
}

int main(void)
{
    if (!read_puzzle())
        return EXIT_FAILURE;

    solve(0, 0, 0, -1);

    if (solution_count == 0) {
        fprintf(stderr,
                "Error: Puzzle has no solution.\n");
        return EXIT_FAILURE;
    }

    if (solution_count > 1) {
        fprintf(stderr,
                "Error: Puzzle has multiple solutions.\n");
        return EXIT_FAILURE;
    }

    print_solution();

    return EXIT_SUCCESS;
}
